 public async ValueTask<IReadOnlyCollection<LiquidationExpense>>ListAsync(LiquidationExpenseFilter f,CancellationToken t){await using var c=await Open(t);await using var cmd=Command("",c);var w=new List<string>();Eq(w,cmd,"[TipoLiqui]","@Type",f.LiquidationType);if(f.LiquidationNumber is not null){w.Add("[ConseLiqui]=@Liquidation");cmd.Parameters.Add("@Liquidation",SqlDbType.Int).Value=f.LiquidationNumber;}Eq(w,cmd,"[CodAgente]","@Employee",f.EmployeeCode);if(f.From is not null){w.Add("[Fecha]>=@From");cmd.Parameters.Add("@From",SqlDbType.Date).Value=f.From.Value.ToDateTime(TimeOnly.MinValue);}if(f.To is not null){w.Add("[Fecha]<DATEADD(day,1,@To)");cmd.Parameters.Add("@To",SqlDbType.Date).Value=f.To.Value.ToDateTime(TimeOnly.MinValue);}Like(w,cmd,"[NumDoc]","@Document",f.DocumentNumber);if(f.Id is not null){w.Add("[DocNum]=@Id");cmd.Parameters.Add("@Id",SqlDbType.Int).Value=f.Id;}if(f.Included is not null){w.Add("[IncluirEnLiquidacion]=@Included");cmd.Parameters.Add("@Included",SqlDbType.Bit).Value=f.Included;}if(!f.IncludeAnnulled)w.Add("ISNULL([Anulado],0)<>1");cmd.CommandText=$"SELECT TOP(500) [DocNum],[Tipo],[NumDoc],[Monto],[Descripcion],[ConseLiqui],[TipoLiqui],[FechaGasto],[CodAgente],[Anulado],[EsFE],[Codigo],[IncluirEnLiquidacion],[EstadoMH] FROM [dbo].[GastosLiquidaciones]{(w.Count==0?"":" WHERE "+string.Join(" AND ",w))} ORDER BY [DocNum] DESC";var a=new List<LiquidationExpense>();await using var r=await cmd.ExecuteReaderAsync(t);while(await r.ReadAsync(t))a.Add(Read(r));return a;}
