 private static void Add(SqlCommand c,LiquidationExpense x){c.Parameters.Add("@Id",SqlDbType.Int).Value=x.Id;P(c,"@Category",100,x.Category);P(c,"@Document",100,x.DocumentNumber);var a=c.Parameters.Add("@Amount",SqlDbType.Decimal);a.Precision=19;a.Scale=4;a.Value=x.Amount;P(c,"@Description",1000,x.Description);c.Parameters.Add("@Liquidation",SqlDbType.Int).Value=(object?)x.LiquidationNumber??DBNull.Value;P(c,"@Type",20,x.LiquidationType);P(c,"@Employee",50,x.EmployeeCode);c.Parameters.Add("@Date",SqlDbType.Date).Value=x.Date.ToDateTime(TimeOnly.MinValue);c.Parameters.Add("@Electronic",SqlDbType.Bit).Value=x.IsElectronicInvoice;P(c,"@Supplier",50,x.SupplierCode);c.Parameters.Add("@Included",SqlDbType.Bit).Value=x.IncludeInLiquidation;c.Parameters.Add("@Time",SqlDbType.NVarChar,6).Value=DateTime.Now.ToString("HHmmss",System.Globalization.CultureInfo.InvariantCulture);}
 private static void Eq(ICollection<string>w,SqlCommand c,string col,string p,string? v){if(string.IsNullOrWhiteSpace(v))return;w.Add($"{col}={p}");P(c,p,100,v);}private static void Like(ICollection<string>w,SqlCommand c,string col,string p,string? v){if(string.IsNullOrWhiteSpace(v))return;w.Add($"{col} LIKE {p}");P(c,p,100,$"%{v.Trim()}%");}private static void P(SqlCommand c,string n,int l,string v)=>c.Parameters.Add(n,SqlDbType.NVarChar,l).Value=v.Trim();private static string T(SqlDataReader r,string n)=>Convert.ToString(r[n])?.Trim()??"";private static bool B(SqlDataReader r,string n)=>r[n] is not DBNull&&(r[n] is bool b?b:Convert.ToInt32(r[n])!=0);private async ValueTask<SqlConnection>Open(CancellationToken t){var c=new SqlConnection(connectionString);await c.OpenAsync(t);return c;}private SqlCommand Command(string s,SqlConnection c,SqlTransaction? t=null)=>new(s,c,t){CommandTimeout=timeout};
